using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    internal sealed class ResponseErrorConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var document = JsonDocument.ParseValue(ref reader);
            return DeserializeResponseError(document.RootElement);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            SerializeResponseError(writer, value);
        }

        private static ResponseError DeserializeResponseError(JsonElement element)
        {
            if (element.ValueKind == JsonValueKind.Null)
            {
                return null;
            }

            // Handle wrapped {"error": {...}} format
            if (element.TryGetProperty("error", out JsonElement errorElement))
            {
                return DeserializeResponseError(errorElement);
            }

            string code = null;
            string message = null;
            string target = null;
            JsonElement additionalInfo = default;
            ResponseInnerError innerError = null;
            List<ResponseError> details = null;

            foreach (var property in element.EnumerateObject())
            {
                switch (property.Name)
                {
                    case "code":
                        code = property.Value.GetString();
                        break;
                    case "message":
                        message = property.Value.GetString();
                        break;
                    case "target":
                        target = property.Value.GetString();
                        break;
                    case "additionalInfo":
                        additionalInfo = property.Value.Clone();
                        break;
                    case "innererror":
                        innerError = DeserializeResponseInnerError(property.Value);
                        break;
                    case "details":
                        if (property.Value.ValueKind == JsonValueKind.Array)
                        {
                            details = new List<ResponseError>();
                            foreach (var item in property.Value.EnumerateArray())
                            {
                                details.Add(DeserializeResponseError(item));
                            }
                        }
                        break;
                }
            }

            return new ResponseError(code, message, target, additionalInfo, innerError, details);
        }

        private static ResponseInnerError DeserializeResponseInnerError(JsonElement element)
        {
            if (element.ValueKind == JsonValueKind.Null)
            {
                return null;
            }

            string code = null;
            ResponseInnerError innerError = null;

            foreach (var property in element.EnumerateObject())
            {
                switch (property.Name)
                {
                    case "code":
                        code = property.Value.GetString();
                        break;
                    case "innererror":
                        innerError = DeserializeResponseInnerError(property.Value);
                        break;
                }
            }

            return new ResponseInnerError(code, innerError);
        }

        private static void SerializeResponseError(Utf8JsonWriter writer, ResponseError value)
        {
            if (value == null)
            {
                writer.WriteNullValue();
                return;
            }

            writer.WriteStartObject();

            if (value.Code != null)
            {
                writer.WriteString("code", value.Code);
            }

            if (value.Message != null)
            {
                writer.WriteString("message", value.Message);
            }

            if (value.Target != null)
            {
                writer.WriteString("target", value.Target);
            }

            if (value.InnerError != null)
            {
                writer.WritePropertyName("innererror");
                SerializeResponseInnerError(writer, value.InnerError);
            }

            if (value.Details != null && value.Details.Count > 0)
            {
                writer.WriteStartArray("details");
                foreach (var detail in value.Details)
                {
                    SerializeResponseError(writer, detail);
                }
                writer.WriteEndArray();
            }

            writer.WriteEndObject();
        }

        private static void SerializeResponseInnerError(Utf8JsonWriter writer, ResponseInnerError value)
        {
            if (value == null)
            {
                writer.WriteNullValue();
                return;
            }

            writer.WriteStartObject();

            if (value.Code != null)
            {
                writer.WriteString("code", value.Code);
            }

            if (value.InnerError != null)
            {
                writer.WritePropertyName("innererror");
                SerializeResponseInnerError(writer, value.InnerError);
            }

            writer.WriteEndObject();
        }
    }
}

